function renderSaved(){$('count').textContent=saved.length;$('saved').replaceChildren();if(!saved.length){const p=document.createElement('p');p.className='empty';p.textContent='Your saved combinations will appear here.';$('saved').append(p);return;}for(const s of saved){const card=document.createElement('article');card.className='saved-card'+(s.id===selected?' selected':'');const load=document.createElement('button');load.className='load';load.setAttribute('aria-label','Load '+s.name);const c=document.createElement('canvas');c.width=215;c.height=400;drawBottle(c,s);const info=document.createElement('div');info.className='card-info';const title=document.createElement('strong');title.textContent=s.name;const chips=document.createElement('div');chips.className='mini-swatches';for(const p of parts){const chip=document.createElement('span');chip.style.background=s.colours[p];chip.title=labels[p]+': '+s.colours[p];chips.append(chip);}info.append(title,chips);load.append(c,info);load.onclick=()=>{state=clone(s);selected=s.id;sync();render();renderSaved();tell('Loaded '+s.name+'. Save creates a new version.');};const actions=document.createElement('div');actions.className='card-actions';const dl=document.createElement('button');dl.textContent='PNG ↓';dl.onclick=()=>exportPNG(s);const del=document.createElement('button');del.textContent='Remove';del.setAttribute('aria-label','Remove '+s.name);del.onclick=()=>{const previous=saved;saved=saved.filter(a=>a.id!==s.id);if(!persist()){saved=previous;return;}renderSaved();tell('Colourway removed.');};actions.append(dl,del);card.append(load,actions);$('saved').append(card);}}
